static const char tt_fold_to[] =
    "aaaaaaceeeeiiiinooooouuuuyaaaaaaceeeeiiiinooooouuuuyyaaaaaaccccc"
    "cccddeeeeeeeeeegggggggghhiiiiiiiiijjkkllllllnnnnnnoooooorrrrrrss"
    "ssssssttttuuuuuuuuuuuuwwyyyzzzzzzoouuaaiioouuuuuuuuuuaaaaggkkooo"
    "ojggnnaaaaaaeeeeiiiioooorrrruuuusstthhaaeeooooooooyyaabbbbbbccdd"
    "ddddddddeeeeeeeeeeffgghhhhhhhhhhiiiikkkkkkllllllllmmmmmmnnnnnnnn"
    "oooooooopppprrrrrrrrssssssssssttttttttuuuuuuuuuuvvvvwwwwwwwwwwxx"
    "xxyyzzzzzzhtwyaaaaaaaaaaaaaaaaaaaaaaaaeeeeeeeeeeeeeeeeiiiioooooo"
    "oooooooooooooooooouuuuuuuuuuuuuuyyyyyyyyka";

static int tt_cp_in(const tt_cp_range *r, size_t n, uint32_t cp)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (cp < r[mid].lo)      hi = mid;
        else if (cp > r[mid].hi) lo = mid + 1;
        else                     return 1;
    }
    return 0;
}

#define TT_N(a) (sizeof(a) / sizeof((a)[0]))

/* ASCII first: it is the common path and it skips the binary search on
 * almost all real text. */
static inline int tt_is_letter(uint32_t cp)
{
    if (cp < 128) return (cp >= 'A' && cp <= 'Z') || (cp >= 'a' && cp <= 'z');
    return tt_cp_in(tt_range_letter, TT_N(tt_range_letter), cp);
}

static inline int tt_is_number(uint32_t cp)
{
    if (cp < 128) return cp >= '0' && cp <= '9';
    return tt_cp_in(tt_range_number, TT_N(tt_range_number), cp);
}

static inline int tt_is_space(uint32_t cp)
{
    if (cp < 128) return cp == ' ' || (cp >= 0x09 && cp <= 0x0D);
    return tt_cp_in(tt_range_space, TT_N(tt_range_space), cp);
}

/* A non-spacing mark contributes NOTHING and does not end a word: on
 * decomposed input "cafe" + U+0301 has to tokenise exactly like the
 * composed "café", which is what NFD makes true in the reference. */
static inline int tt_is_mark(uint32_t cp)
{
    if (cp < 128) return 0;
    return tt_cp_in(tt_range_mark, TT_N(tt_range_mark), cp);
}

/* The ASCII letter or digit `cp` folds to, 0 for none.  Lowercase, then
 * canonical decomposition, then the marks dropped -- so U+1E63 (s with a
 * dot below, which the corpus uses for Sanskrit) folds to 's' and
 * "puruṣa" indexes as one term instead of two fragments. */
static inline int tt_fold_ascii(uint32_t cp)
{
    if (cp < 128) {
        if (cp >= 'A' && cp <= 'Z') return (int)cp + 32;
        if ((cp >= 'a' && cp <= 'z') || (cp >= '0' && cp <= '9')) return (int)cp;
        return 0;
    }
    size_t lo = 0, hi = TT_N(tt_fold_from);
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (cp < tt_fold_from[mid])      hi = mid;
        else if (cp > tt_fold_from[mid]) lo = mid + 1;
        else return (unsigned char)tt_fold_to[mid];
    }
    return 0;
}

